entries.content:
[PAWN PROFILES LAYER]

{{~ # Engineering Hack: Define a literal newline variable ~}}
{{~ capture nl ~}}
{{~ "" }}
{{~ end ~}}

{{ for p in pawns}}
# PROFILE: {{ p.name }}
Full Name: {{ p.fullname }}
Gender: {{ p.gender }}
Age: {{ p.age }}
Faction: {{p.faction }}
{{~ 
  # Clean and Rename conflicting memory tag
  profile_text = p.profile | StripFormattingTags | string.replace "Memory:" "Current Mood Modifiers:" 
~}}
{{- for line in (profile_text | string.split nl | array.offset 2) }}
{{ line }}
{{- end }}

# {{ p.name }}'s Current Activity:
{{ p.job | string.capitalize | StripFormattingTags }}

# {{ p.name }}'s Inventory:
{{~ if p.inventory.innerContainer.Count > 0 ~}}
{{- for line in p.inventory.innerContainer -}}
{{ line.LabelCap | StripFormattingTags }}
{{ end -}}
{{~ else ~}}
- (no items held)
{{~ end ~}}

# {{ p.name }}'s Needs:
Mood: {{ p.needs.mood.MoodString }}
{{ for need in p.needs.AllNeeds | array.offset 1 -}}{{- if need.CurCategory | string.size > 0 -}}{{ need.Def }}: {{ need.CurCategory }}
{{ end }}{{ end }}

# {{ p.name }}'s Status & Eligibility
IsColonist: {{ p.IsColonist }}
IsBaby: {{ IsBaby p }}
IsVisitor: {{ IsVisitor p }}
IsEnemy: {{ IsEnemy p }}
IsSlave: {{ p.IsSlave }}
IsPrisoner: {{ p.IsPrisoner }}
InCombat: {{ IsInCombat p }}
InDanger: {{ IsInDanger p }}
CanTalk: {{ IsTalkEligible p }}

## {{ p.name }}'s Recent Memories & Perspective - REFERENCE ONLY:

# Internal Perspective
{{- for line in (StripFormattingTags p.et_thoughts | string.split nl | array.offset  1) }}
{{ line }}
{{- end }}

# Chronological Events
{{ p.memory }}

#  {{ p.name }}'s Location & Surroundings
Location: {{ p.location }}
Location Beauty: {{ p.beauty }}
Location Terrain: {{ p.terrain }}
Location Cleanliness: {{ p.cleanliness }}
Things Around {{ p.name }}:
{{- for line in p.surroundings  | string.split nl}}
- {{ line }}
{{- end }}
{{ end -}}

[COLONY STATUS - THEMATIC WEIGHTS]
# INSTRUCTION: The Scene Director MUST treat the following data as environmental pressure and narrative fuel.

- CONCEPTUAL TRANSLATION: The Scene Director MUST separate "System Labels" from "Narrative Nouns."
    * MECHANICAL LABELS: The Scene Director MUST NOT use game-engine terminology (e.g., "Raid," "Quest," "Manhunter," "Cold Snap," "Toxic Fallout"). 
    * NARRATIVE NOUNS: The Scene Director MAY use the names of specific persons (e.g., "Idris"), factions, or locations found within the data as the "Villains" and "Vows" of the story.

- SENSORY RECONSTRUCTION: If a [THREAT] or [MAP CONDITION] lacks a personal name, the Scene Director MUST describe its physical impact exclusively. 
    * Logic: The Scene Director SHOULD focus on what the pawn sees, hears, or fears (e.g., the state of the sky, the sound of the enemy, or the pain of the cold).

- THE VOW PROTOCOL: The Scene Director MUST frame [ACTIVE QUESTS] as social or moral obligations. 
    * Logic: The Scene Director MUST refer to the quest's objective (the person to save, the beast to slay, the debt to pay) and MUST NOT refer to its title.

[THREATS]
{{ if eventplus_threats != "" -}}
{{ eventplus_threats }}
{{ else }}
No active threats.

{{ end -}}

[MAP CONDITIONS]
{{ if eventplus_conditions != "" -}}
{{ eventplus_conditions }}
{{ else }}
No active map conditions.

{{ end -}}

[ACTIVE QUESTS]
{{ if eventplus_quests != "" -}}
{{ eventplus_quests }}
{{ else }}
No active quests.

{{ end -}}
